function step(ctx) {
  const workers = ctx.game.units({team:ctx.myTeam, limit:32768}).filter(u => u.type === 0).length;
  return {output:{workers}};
}

function step(ctx) {
  const buildings = ctx.game.buildings({team:ctx.myTeam, limit:32768});
  return {output:{inns:buildings.filter(b => b.shortType === 1).length}};
}

function step(ctx) {
  const buildings = ctx.game.buildings({team: ctx.myTeam, limit: 32768});
  return {output: {buildings: buildings.map(b => ({id: b.id, generation: b.generation, team: b.team}))}};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0);
 return {output:{swarms:swarms.map(b=>({id:b.id,generation:b.generation,construction:b.construction,production:b.production}))}};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && b.construction===0);
 return {output:{queued:swarms.length},orders:swarms.map(b=>({type:'production',building:{id:b.id,generation:b.generation},ratios:[8,0,0]})).slice(0,32)};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0);
 return {output:{swarms:swarms.map(b=>({id:b.id,generation:b.generation,construction:b.construction,production:b.production}))}};
}

function step(ctx) {
  const swarms = ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && b.construction===0);
  const orders = swarms.map(b=>({type:'production',building:{id:b.id,generation:b.generation},ratios:[3,2,1]})).slice(0,32);
  return {output:{tick:ctx.tick,swarms:swarms.map(b=>({id:b.id,generation:b.generation,production:b.production})),queued:orders.length},orders};
}

function step(ctx) {
  const swarms = ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && b.construction===0);
  return {output:{tick:ctx.tick,swarms:swarms.map(b=>({id:b.id,generation:b.generation,production:b.production}))}};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && !b.virtual);
 return {output:{swarms:swarms.map(b=>({id:b.id,generation:b.generation,workers:b.workers,construction:b.construction}))}};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && !b.virtual && b.construction===0);
 return {output:{requested:swarms.length},orders:swarms.slice(0,32).map(b=>({type:'workers',building:{id:b.id,generation:b.generation},workers:7}))};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.shortType===0 && !b.virtual);
 return {output:{swarms:swarms.map(b=>({id:b.id,generation:b.generation,workers:b.workers,construction:b.construction}))}};
}

function step(ctx) {
 const swarms=ctx.game.buildings({team:ctx.myTeam,limit:100}).filter(b=>b.shortType===0 && !b.virtual);
 return {output:{swarms:swarms.map(b=>({id:b.id,generation:b.generation,priority:b.priority,construction:b.construction}))}};
}

function step(ctx) {
 const b=ctx.game.building({id:0,generation:1});
 if (!b || b.team!==ctx.myTeam || b.shortType!==0) return {output:{status:'not-found'}};
 return {output:{queued:true},orders:[{type:'priority',building:{id:b.id,generation:b.generation},priority:-1}]};
}

function step(ctx) {
 const b=ctx.game.building({id:0,generation:1});
 return {output:b && b.team===ctx.myTeam && b.shortType===0 ? {id:b.id,priority:b.priority} : {status:'not-found'}};
}

function step(ctx) {
  const buildings = ctx.game.buildings({team:ctx.myTeam,limit:200});
  const innSite = ctx.game.buildingTypes().find(t => t.name === 'inn' && t.level === 0 && t.site && !t.virtual);
  const atTile = buildings.find(b => b.x === 18 && b.y === 4 && b.shortType === 1 && b.construction === 1);
  if (atTile) return {output:{status:'exists',building:{id:atTile.id,generation:atTile.generation,x:atTile.x,y:atTile.y,workers:atTile.workers,futureWorkers:atTile.futureWorkers}}};
  if (!innSite) return {output:{status:'no-level-zero-inn-site-type'}};
  return {output:{status:'order-queued',buildingType:innSite.id},orders:[{type:'create',buildingType:innSite.id,x:18,y:4,workers:3,futureWorkers:2}]};
}

function step(ctx) {
  const buildings = ctx.game.buildings({team:ctx.myTeam,limit:200});
  const b = buildings.find(b => b.x === 18 && b.y === 4 && b.shortType === 1 && b.construction === 1);
  return {output:b ? {status:'exists',building:{id:b.id,generation:b.generation,x:b.x,y:b.y,workers:b.workers,futureWorkers:b.futureWorkers}} : {status:'not-yet-observed'}};
}

function step(ctx) {
  const types = ctx.game.buildingTypes();
  const school = types.find(t => t.name === 'school' && t.level === 0 && t.site && !t.virtual);
  if (!school) return {output:{error:'No level-zero school construction site variant found.'}};
  const buildings = ctx.game.buildings({team:ctx.myTeam,limit:32768});
  const existing = buildings.find(b => b.type === school.id && b.x === 18 && b.y === 10 && b.construction === 1);
  if (existing) return {output:{status:'already-present',site:{id:existing.id,generation:existing.generation,type:existing.type,x:existing.x,y:existing.y,construction:existing.construction,workers:existing.workers,futureWorkers:existing.futureWorkers}}};
  return {output:{schoolType:school.id},orders:[{type:'create',buildingType:school.id,x:18,y:10,workers:2,futureWorkers:1}]};
}
function step(ctx) {
  const types = ctx.game.buildingTypes();
  const school = types.find(t => t.name === 'school' && t.level === 0 && t.site && !t.virtual);
  if (!school) return {output:{verified:false,reason:'No level-zero school construction site variant found.'}};
  const buildings = ctx.game.buildings({team:ctx.myTeam,limit:32768});
  const site = buildings.find(b => b.type === school.id && b.x === 18 && b.y === 10 && b.construction === 1);
  return {output:site ? {verified:true,site:{id:site.id,generation:site.generation,type:site.type,x:site.x,y:site.y,construction:site.construction,workers:site.workers,futureWorkers:site.futureWorkers}} : {verified:false,schoolType:school.id,reason:'No matching construction site is currently observed.'}};
}

function step(ctx) {
  const flags = ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.virtual && b.shortType===8);
  const existing = flags.find(b=>b.x===20 && b.y===8);
  if (existing) return {output:{status:'exists',flag:{id:existing.id,generation:existing.generation,x:existing.x,y:existing.y,range:existing.range,workers:existing.workers,minimumLevel:existing.minimumLevel}}};
  const type = ctx.game.buildingTypes().find(t=>t.shortType===8 && t.virtual);
  if (!type) return {output:{status:'failed',reason:'No exploration-flag variant is registered.'}};
  return {output:{status:'queued',type:type.id},orders:[{type:'create',buildingType:type.id,x:20,y:8,workers:2,futureWorkers:2,range:4}]};
}

function step(ctx) {
  const flags = ctx.game.buildings({team:ctx.myTeam,limit:200}).filter(b=>b.virtual && b.shortType===8 && b.x===20 && b.y===8);
  return {output:{tick:ctx.tick,exists:flags.length>0,flags:flags.map(b=>({id:b.id,generation:b.generation,x:b.x,y:b.y,range:b.range,workers:b.workers,minimumLevel:b.minimumLevel}))}};
}

function step(ctx) {
  const swarms = ctx.game.buildings({team:ctx.myTeam, limit:200}).filter(b => b.shortType === 0 && b.construction === 0);
  return {
    output: {swarms: swarms.length, tick: ctx.tick},
    orders: swarms.slice(0, 32).map(b => ({type: 'production', building: {id: b.id, generation: b.generation}, ratios: [5, 1, 2]}))
  };
}

function step(ctx) {
  const swarms = ctx.game.buildings({team:ctx.myTeam, limit:200}).filter(b => b.shortType === 0 && b.construction === 0);
  return {output: swarms.map(b => ({id: b.id, generation: b.generation, production: b.production}))};
}

let populationReadySent = false;
function step(ctx) {
  const workers = ctx.game.units({team: ctx.myTeam, limit: 32768}).filter(u => u.type === 0).length;
  if (workers >= 10 && !populationReadySent) {
    populationReadySent = true;
    ctx.wakeAgent({key: 'population-ready', reason: 'Worker population has reached at least 10.', data: {workers, tick: ctx.tick}});
  }
  return {output: {workers, populationReadySent}};
}

let woke = false;
function step(ctx) {
  const inns = ctx.game.buildings({team:ctx.myTeam, limit:200}).filter(b => b.shortType === 1);
  if (!woke && inns.length > 0) {
    woke = true;
    ctx.wakeAgent({key:'inn-ready', reason:'An owned inn is present.', data:{tick:ctx.tick, count:inns.length}});
  }
  return {output:{tick:ctx.tick, inns:inns.length, woke}};
}
